      setTimeout(() => {
        this.playNoise(0.04, 600 + Math.random() * 400, 'bandpass', 0.25);
      }, i * 30);
    }
  }

  // Go Fish - gentle descending tone
  playGoFish() {
    this.playTone(400, 0.15, 'sine', 0.6);
    setTimeout(() => this.playTone(300, 0.2, 'sine', 0.5), 100);
  }

  // Success - soft chime
  playSuccess() {
    this.playTone(523, 0.08, 'sine', 0.5);
    setTimeout(() => this.playTone(659, 0.1, 'sine', 0.4), 80);
  }

  // Book completion - gentle flourish
  playBook() {
    this.playTone(392, 0.08, 'sine', 0.4);
    setTimeout(() => this.playTone(523, 0.08, 'sine', 0.4), 70);
    setTimeout(() => this.playTone(659, 0.12, 'sine', 0.5), 140);
