    setTimeout(() => this.playTone(330, 0.25, 'sine', 0.4), 180);
  }

  // UI click - very subtle
  playClick() {
    this.playNoise(0.03, 1200);
  }

  // Background music using oscillators
  startMusic() {
    if (!this.musicEnabled || this.musicPlaying) return;
    
    try {
      this.init();
      this.musicPlaying = true;
      this.playMusicLoop();
    } catch (e) {
      console.log('Music not available');
    }
  }

  playMusicLoop() {
    if (!this.musicPlaying || !this.musicEnabled) return;

    // Simple calm melody loop
    const melody = [
      { freq: 329, dur: 0.4 }, // E4
      { freq: 392, dur: 0.4 }, // G4
      { freq: 440, dur: 0.4 }, // A4
      { freq: 392, dur: 0.4 }, // G4
      { freq: 329, dur: 0.4 }, // E4
      { freq: 294, dur: 0.4 }, // D4
      { freq: 329, dur: 0.8 }, // E4
      { freq: 0, dur: 0.4 },   // rest
      { freq: 392, dur: 0.4 }, // G4
      { freq: 440, dur: 0.4 }, // A4
      { freq: 494, dur: 0.4 }, // B4
      { freq: 440, dur: 0.4 }, // A4
      { freq: 392, dur: 0.4 }, // G4
      { freq: 329, dur: 0.8 }, // E4
      { freq: 0, dur: 0.4 },   // rest
    ];

    let time = 0;
    melody.forEach(note => {
      if (note.freq > 0) {
        setTimeout(() => {
